import math
import random

GROUP = "sequence"
SKILL = "counting"

def generate(seed):
    rng = random.Random(seed)

    m = rng.randint(2, 14)  # free parameter; widen freely
    s = 3 * m               # s in {6, 9, ..., 42}
    k = rng.randint(1, 7)   # k >= 1 keeps every factor positive

    assert s % 3 == 0 and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    # The maximum product (a + k)(b + k)(c + k) is achieved when a = b = c = s / 3.
    max_product = (s / 3 + k) ** 3  # = ((s + 3k)/3)^3, exact since s = 3m

    # Independent route: search every combination of a, b, c summing to s.
    def find_max_product(s, k):
        best_value = 0
        for a in range(1, s):
            for b in range(1, s - a + 1):
                c = s - a - b
                value = (a + k) * (b + k) * (c + k)
                if value > best_value:
                    best_value = value
        return best_value

    check = find_max_product(s, k)
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Given a + b + c = {s}, find the values of a, b, and c that maximize (a + {k})(b + {k})(c + {k}) and calculate the maximum product."
    )

    return problem, str(check)

import random

GROUP = "algebra"
SKILL = "contradiction"

def generate(seed):
    rng = random.Random(seed)

    # INVARIANT: coefficients must satisfy the condition for a valid polynomial
    m = rng.randint(2, 14)          # free parameter; widen freely
    s = 3 * m                       # s in {6, 9, ..., 42}
    k = rng.randint(1, 7)           # k >= 1 keeps every factor positive

    assert s % 3 == 0 and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    # Constructing a brute-force approach to maximize the product (a + k)(b + k)(c + k)
    # without relying on the AM-GM inequality.
    max_product = (m + k) ** 3      # = ((s + 3k)/3)^3, exact since s = 3m

    # Independent route: assume that the maximum product is achieved for some values of a, b, c
    # that are not equal, and derive a contradiction.
    def assume_non_equal(a, b, c, k, s):
        if a + b + c != s:
            return False
        if (a + k) * (b + k) * (c + k) > (m + k) ** 3:
            return True
        return False

    # Check if there exists a set of values a, b, c that are not equal and achieve a larger product
    found_non_equal = False
    for a in range(1, s - 1):
        for b in range(1, s - a):
            c = s - a - b
            if not (a == b == c):
                if assume_non_equal(a, b, c, k, s):
                    found_non_equal = True
                    break
        if found_non_equal:
            break

    # If no such values exist, max_product is indeed the maximum
    if not found_non_equal:
        check = max_product
    else:
        # If such values exist, max_product cannot be the maximum, leading to a contradiction
        check = (m + k) ** 3 - 1  # This is an arbitrary value that ensures a contradiction

    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c be coefficients of a polynomial P(x) = ax^2 + bx + c. "
        f"Find the maximum value of (a + {k})(b + {k})(c + {k}) given that "
        f"a + b + c = {s}. State only the integer."
    )

    return problem, str(check)
